import sys
from collections import deque

def solve():
    input = sys.stdin.read().split()
    ptr = 0
    t = int(input[ptr])
    ptr += 1
    for _ in range(t):
        n, k = map(int, input[ptr:ptr+2])
        ptr +=2
        x = list(map(int, input[ptr:ptr+k]))
        ptr +=k
        adj = [[] for _ in range(n+1)]
        for __ in range(n-1):
            u, v = map(int, input[ptr:ptr+2])
            ptr +=2
            adj[u].append(v)
            adj[v].append(u)

        leaves = []
        for i in range(1, n+1):
            if len(adj[i]) == 1:
                leaves.append(i)

        if k == 0:
            print("YES")
            continue

        if 1 in x:
            print("NO")
            continue

        if len(leaves) == 1:
            print("NO")
            continue

        if len(leaves) == 2 and leaves[0] == 1 and leaves[1] != 1:
            print("NO")
            continue

        if len(leaves) == 2 and leaves[0] != 1 and leaves[1] != 1:
            print("YES")
            continue

        parent = [0]*(n+1)
        q = deque([1])
        parent[1] = 0
        while q:
            u = q.popleft()
            for v in adj[u]:
                if parent[v] == 0 and v != parent[u]:
                    parent[v] = u
                    q.append(v)

        dist = [0]*(n+1)
        q = deque([1])
        dist[1] = 0
        while q:
            u = q.popleft()
            for v in adj[u]:
                if dist[v] == 0 and v != parent[u]:
                    dist[v] = dist[u] + 1
                    q.append(v)

        max_dist = max(dist[1:])
        if max_dist == 1:
            print("NO")
            continue

        friend_pos = set(x)
        possible = False
        for leaf in leaves:
            if leaf == 1:
                continue
            if leaf not in friend_pos:
                possible = True
                break

        if possible:
            print("YES")
        else:
            print("NO")

solve()
